-- 中文操作说明：独立病历来源/专业复核五表；请按01预检、02升级、03后检顺序操作。
-- 目标仅MySQL 5.7.18（允许真实供应商后缀如-txsql，拒绝MariaDB）；不声称5.7.18+或8.x通过验证。
-- root/CN是两种替代部署，只选与既有系统对应的一套；不在同库混跑。
-- 先验证完整可恢复备份、目标库、权限、空间；停写并排空旧writer，SQL先于代码，feature默认关闭。
-- 使用支持DELIMITER的mysql --batch --default-character-set=utf8mb4 ... --password --database=DB < FILE.sql。
-- 禁止--force、忽略错误、RunSqlMigration分号splitter和盲补DDL；任何错误立即停止并保持停写。
-- 01仅检查元数据；ABSENT输出REVIEW_PRECHECK_OK；精确READY输出REVIEW_ALREADY_READY并跳过02；其他BLOCKED。
-- 02仅ABSENT可运行；非原子DDL隐式提交，可能等待元数据锁；部分失败不能自动修复/重跑；03须独立确认。
-- 不改原生表、原生触发器、旧SQL或旧doctor_review_log；不回填、不删除业务数据、不启用feature。
-- 五张新表为单一READY单元。触发器仅守护新表；当前state/text/command可合法清理，event/reference保留无正文事实。
-- 实际删除事实、权限、锁序、原生删除成功及beforeCommit校验必须由应用事务保证；DDL不能替代应用闭环。
-- 本文件仅提供SQL源文；原生MySQL语法、元数据、触发器/级联/锁行为、性能及生产部署均未经本交付验证。
-- 预检/后检仅覆盖当前账户可见元数据；执行账户须能检查相关表、触发器及跨库引用；不保证发现不可见对象，不自动GRANT或改变权限。

SET @mrv57_ready=(SELECT CASE WHEN
  DATABASE() IS NOT NULL AND
  (VERSION()='5.7.18' OR VERSION() LIKE '5.7.18-%') AND LOWER(VERSION()) NOT LIKE '%mariadb%' AND
  (FIND_IN_SET('STRICT_TRANS_TABLES',@@SESSION.sql_mode)>0 OR FIND_IN_SET('STRICT_ALL_TABLES',@@SESSION.sql_mode)>0) AND
  @@SESSION.foreign_key_checks=1 AND
  @@SESSION.unique_checks=1 AND
  (SELECT COUNT(*) FROM information_schema.TABLES WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record' AND TABLE_TYPE='BASE TABLE' AND ENGINE='InnoDB')=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record' AND BINARY COLUMN_NAME=BINARY 'id' AND LOWER(COLUMN_TYPE)='bigint(20)' AND IS_NULLABLE='NO' AND LOWER(EXTRA)='auto_increment' AND CHARACTER_SET_NAME IS NULL)=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record' AND BINARY COLUMN_NAME=BINARY 'patient_name' AND LOWER(COLUMN_TYPE)='varchar(50)' AND IS_NULLABLE='NO' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME='utf8mb4')=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record' AND BINARY COLUMN_NAME=BINARY 'patient_id' AND LOWER(COLUMN_TYPE)='bigint(20)' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME IS NULL)=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record' AND BINARY COLUMN_NAME=BINARY 'user_id' AND LOWER(COLUMN_TYPE)='bigint(20)' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME IS NULL)=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record' AND BINARY COLUMN_NAME=BINARY 'record_date' AND LOWER(COLUMN_TYPE)='date' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME IS NULL)=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record' AND BINARY COLUMN_NAME=BINARY 'record_type' AND LOWER(COLUMN_TYPE)='varchar(30)' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME='utf8mb4')=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record' AND BINARY COLUMN_NAME=BINARY 'hospital_name' AND LOWER(COLUMN_TYPE)='varchar(100)' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME='utf8mb4')=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record' AND BINARY COLUMN_NAME=BINARY 'dept_name' AND LOWER(COLUMN_TYPE)='varchar(100)' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME='utf8mb4')=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record' AND BINARY COLUMN_NAME=BINARY 'doctor_name' AND LOWER(COLUMN_TYPE)='varchar(50)' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME='utf8mb4')=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record' AND BINARY COLUMN_NAME=BINARY 'ai_raw_result' AND LOWER(COLUMN_TYPE)='text' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME='utf8mb4')=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record' AND BINARY COLUMN_NAME=BINARY 'source_type' AND LOWER(COLUMN_TYPE)='varchar(20)' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME='utf8mb4')=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record' AND BINARY COLUMN_NAME=BINARY 'import_facts_json' AND LOWER(COLUMN_TYPE)='text' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME='utf8mb4')=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record' AND BINARY COLUMN_NAME=BINARY 'source_external_id' AND LOWER(COLUMN_TYPE)='varchar(120)' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME='utf8mb4')=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record' AND BINARY COLUMN_NAME=BINARY 'verification_status' AND LOWER(COLUMN_TYPE)='varchar(30)' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME='utf8mb4')=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record' AND BINARY COLUMN_NAME=BINARY 'confidence_score' AND LOWER(COLUMN_TYPE)='decimal(5,4)' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME IS NULL)=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record' AND BINARY COLUMN_NAME=BINARY 'verified_by' AND LOWER(COLUMN_TYPE)='bigint(20)' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME IS NULL)=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record' AND BINARY COLUMN_NAME=BINARY 'verified_at' AND LOWER(COLUMN_TYPE)='datetime' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME IS NULL)=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record' AND BINARY COLUMN_NAME=BINARY 'content_version' AND LOWER(COLUMN_TYPE)='bigint(20)' AND IS_NULLABLE='NO' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME IS NULL)=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record' AND BINARY COLUMN_NAME=BINARY 'verification_note' AND LOWER(COLUMN_TYPE)='text' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME='utf8mb4')=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record' AND BINARY COLUMN_NAME=BINARY 'remark' AND LOWER(COLUMN_TYPE)='varchar(500)' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME='utf8mb4')=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record' AND BINARY COLUMN_NAME=BINARY 'created_at' AND LOWER(COLUMN_TYPE)='datetime' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME IS NULL)=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record' AND BINARY COLUMN_NAME=BINARY 'updated_at' AND LOWER(COLUMN_TYPE)='datetime' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='on update current_timestamp' AND CHARACTER_SET_NAME IS NULL)=1 AND
  (SELECT COUNT(*) FROM information_schema.STATISTICS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record' AND BINARY INDEX_NAME='PRIMARY')=1 AND
  (SELECT COUNT(*) FROM information_schema.STATISTICS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record' AND BINARY INDEX_NAME='PRIMARY' AND NON_UNIQUE=0 AND SEQ_IN_INDEX=1 AND BINARY COLUMN_NAME='id' AND SUB_PART IS NULL AND INDEX_TYPE='BTREE' AND COLLATION='A')=1 AND
  (SELECT COUNT(*) FROM information_schema.TABLES WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record_item' AND TABLE_TYPE='BASE TABLE' AND ENGINE='InnoDB')=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record_item' AND BINARY COLUMN_NAME=BINARY 'id' AND LOWER(COLUMN_TYPE)='bigint(20)' AND IS_NULLABLE='NO' AND LOWER(EXTRA)='auto_increment' AND CHARACTER_SET_NAME IS NULL)=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record_item' AND BINARY COLUMN_NAME=BINARY 'record_id' AND LOWER(COLUMN_TYPE)='bigint(20)' AND IS_NULLABLE='NO' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME IS NULL)=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record_item' AND BINARY COLUMN_NAME=BINARY 'item_name' AND LOWER(COLUMN_TYPE)='varchar(200)' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME='utf8mb4')=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record_item' AND BINARY COLUMN_NAME=BINARY 'item_code' AND LOWER(COLUMN_TYPE)='varchar(50)' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME='utf8mb4')=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record_item' AND BINARY COLUMN_NAME=BINARY 'result_value' AND LOWER(COLUMN_TYPE)='varchar(500)' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME='utf8mb4')=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record_item' AND BINARY COLUMN_NAME=BINARY 'unit' AND LOWER(COLUMN_TYPE)='varchar(50)' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME='utf8mb4')=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record_item' AND BINARY COLUMN_NAME=BINARY 'reference_range' AND LOWER(COLUMN_TYPE)='varchar(200)' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME='utf8mb4')=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record_item' AND BINARY COLUMN_NAME=BINARY 'is_abnormal' AND LOWER(COLUMN_TYPE)='tinyint(4)' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME IS NULL)=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record_item' AND BINARY COLUMN_NAME=BINARY 'ai_confidence' AND LOWER(COLUMN_TYPE)='decimal(5,4)' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME IS NULL)=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record_item' AND BINARY COLUMN_NAME=BINARY 'created_at' AND LOWER(COLUMN_TYPE)='datetime' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME IS NULL)=1 AND
  (SELECT COUNT(*) FROM information_schema.STATISTICS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record_item' AND BINARY INDEX_NAME='PRIMARY')=1 AND
  (SELECT COUNT(*) FROM information_schema.STATISTICS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record_item' AND BINARY INDEX_NAME='PRIMARY' AND NON_UNIQUE=0 AND SEQ_IN_INDEX=1 AND BINARY COLUMN_NAME='id' AND SUB_PART IS NULL AND INDEX_TYPE='BTREE' AND COLLATION='A')=1 AND
  (SELECT COUNT(*) FROM information_schema.TABLES WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record_attachment' AND TABLE_TYPE='BASE TABLE' AND ENGINE='InnoDB')=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record_attachment' AND BINARY COLUMN_NAME=BINARY 'id' AND LOWER(COLUMN_TYPE)='bigint(20)' AND IS_NULLABLE='NO' AND LOWER(EXTRA)='auto_increment' AND CHARACTER_SET_NAME IS NULL)=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record_attachment' AND BINARY COLUMN_NAME=BINARY 'record_id' AND LOWER(COLUMN_TYPE)='bigint(20)' AND IS_NULLABLE='NO' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME IS NULL)=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record_attachment' AND BINARY COLUMN_NAME=BINARY 'file_path' AND LOWER(COLUMN_TYPE)='varchar(500)' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME='utf8mb4')=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record_attachment' AND BINARY COLUMN_NAME=BINARY 'file_name' AND LOWER(COLUMN_TYPE)='varchar(200)' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME='utf8mb4')=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record_attachment' AND BINARY COLUMN_NAME=BINARY 'file_type' AND LOWER(COLUMN_TYPE)='varchar(20)' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME='utf8mb4')=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record_attachment' AND BINARY COLUMN_NAME=BINARY 'file_size' AND LOWER(COLUMN_TYPE)='bigint(20)' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME IS NULL)=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record_attachment' AND BINARY COLUMN_NAME=BINARY 'file_content' AND LOWER(COLUMN_TYPE)='mediumtext' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME='utf8mb4')=1 AND
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record_attachment' AND BINARY COLUMN_NAME=BINARY 'created_at' AND LOWER(COLUMN_TYPE)='datetime' AND IS_NULLABLE='YES' AND LOWER(EXTRA)='' AND CHARACTER_SET_NAME IS NULL)=1 AND
  (SELECT COUNT(*) FROM information_schema.STATISTICS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record_attachment' AND BINARY INDEX_NAME='PRIMARY')=1 AND
  (SELECT COUNT(*) FROM information_schema.STATISTICS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_record_attachment' AND BINARY INDEX_NAME='PRIMARY' AND NON_UNIQUE=0 AND SEQ_IN_INDEX=1 AND BINARY COLUMN_NAME='id' AND SUB_PART IS NULL AND INDEX_TYPE='BTREE' AND COLLATION='A')=1 AND
  (SELECT COUNT(*) FROM information_schema.TABLES WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY LEFT(LOWER(TABLE_NAME),15)=BINARY 'medical_review_')=5 AND
  (SELECT COUNT(*) FROM information_schema.TABLES WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_review_event' AND TABLE_TYPE='BASE TABLE' AND ENGINE='InnoDB' AND ROW_FORMAT='Dynamic' AND TABLE_COLLATION='utf8mb4_bin')=1 AND
  (SELECT COUNT(*) FROM information_schema.PARTITIONS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_review_event')=1 AND
  (SELECT COUNT(*) FROM information_schema.PARTITIONS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_review_event' AND PARTITION_NAME IS NULL AND SUBPARTITION_NAME IS NULL)=1 AND
