 LOWER(EXTRA)='' AND ORDINAL_POSITION=8 AND CHARACTER_SET_NAME IS NULL AND COLLATION_NAME IS NULL AND GENERATION_EXPRESSION='') THEN 1 ELSE 0 END)=8 FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=BINARY 'medical_review_reference') AND
