  (SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE BINARY TRIGGER_SCHEMA=BINARY DATABASE() AND (BINARY LEFT(LOWER(EVENT_OBJECT_TABLE),15)=BINARY 'medical_review_' OR BINARY LEFT(LOWER(TRIGGER_NAME),6)=BINARY 'mrv57_'))=13 AND
