  (SELECT COUNT(*) FROM information_schema.STATISTICS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY LEFT(LOWER(INDEX_NAME),6)=BINARY 'mrv57_')=27 AND
