END' AND CHARACTER_SET_CLIENT='utf8mb4' AND COLLATION_CONNECTION='utf8mb4_bin' AND (FIND_IN_SET('STRICT_TRANS_TABLES',SQL_MODE)>0 OR FIND_IN_SET('STRICT_ALL_TABLES',SQL_MODE)>0))=1 AND
  (SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE BINARY TRIGGER_SCHEMA=BINARY DATABASE() AND BINARY TRIGGER_NAME=BINARY 'mrv57_event_id' AND BINARY EVENT_OBJECT_TABLE=BINARY 'medical_review_event' AND ACTION_TIMING='AFTER' AND EVENT_MANIPULATION='INSERT' AND ACTION_ORIENTATION='ROW' AND ACTION_ORDER=1 AND BINARY REPLACE(ACTION_STATEMENT,CHAR(13),'')=BINARY 'BEGIN
